#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 3) {
        printf("Usage: %s <num_nodes> <num_edges>\n", argv[0]);
        return 1;
    }

    int num_nodes = atoi(argv[1]);
    int num_edges = atoi(argv[2]);

    // Initialize adjacency matrix
    int **adj = (int **)malloc(num_nodes * sizeof(int *));
    for (int i = 0; i < num_nodes; i++) {
        adj[i] = (int *)malloc(num_nodes * sizeof(int));
    }

    // Initialize visited array
    int *visited = (int *)malloc(num_nodes * sizeof(int));
    for (int i = 0; i < num_nodes; i++) {
        visited[i] = 0;
    }

    // Initialize queue
    int *queue = (int *)malloc(num_nodes * sizeof(int));

    // Read edges from input
    for (int i = 0; i < num_edges; i++) {
        int u, v;
        sscanf(argv[3 + 2 * i], "%d", &u);
        sscanf(argv[3 + 2 * i + 1], "%d", &v);
        adj[u][v] = 1;
        adj[v][u] = 1;
    }

    // Perform BFS
    for (int i = 0; i < num_nodes; i++) {
        if (!visited[i]) {
            printf("%d: ", i);
            queue[0] = i;
            int front = 0, rear = 1;
            visited[i] = 1;
            while (front < rear) {
                int node = queue[front];
                front++;
                for (int j = 0; j < num_nodes; j++) {
                    if (adj[node][j] && !visited[j]) {
                        queue[rear] = j;
                        rear++;
                        visited[j] = 1;
                        printf("%d ", j);
                    }
                }
            }
            printf("\n");
        }
    }

    return 0;
}
